/**
 * Drop Node's one-time `node:sqlite` ExperimentalWarning.
 * Every other warning keeps the normal Node output.
 */
const SQLITE_EXPERIMENTAL_WARNING_PREFIX = "SQLite is an experimental feature";
let installed = false;
export function installSqliteExperimentalWarningFilter() {
    if (installed) {
        return;
    }
    installed = true;
    const emitWarning = process.emitWarning.bind(process);
    const filtered = function filteredEmitWarning(warning, ...args) {
        if (typeof warning === "string" &&
            args[0] === "ExperimentalWarning" &&
            warning.startsWith(SQLITE_EXPERIMENTAL_WARNING_PREFIX)) {
            return;
        }
        Reflect.apply(emitWarning, process, [warning, ...args]);
    };
    process.emitWarning = filtered;
}
